import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.BSa2j5Vp.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md"}'),n={name:"guide/configuration.md"};function r(i,e,s,c,l,u){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>All knobs are process environment variables, read once when the plugin loads (OpenCode does not forward per-model plugin options, so an <code>opencode.json</code> field cannot reach the bridge). Restart OpenCode after changing one.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Values</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>OPENCODE_MUSE_CONTRIBUTOR_MODE</code></td><td><code>on</code> / <code>off</code></td><td><code>on</code></td><td>Billing lane for spawned Muse children</td></tr><tr><td><code>OPENCODE_MUSE_TOOL_BACKEND</code></td><td><code>muse</code> / <code>opencode</code></td><td><code>muse</code></td><td>Who executes tools (see below)</td></tr><tr><td><code>OPENCODE_MUSE_APPROVAL_MODE</code></td><td><code>onRequest</code> / <code>host-default</code> / <code>allowAll</code> / <code>promptUnmatched</code> / <code>denyUnmatched</code></td><td><code>onRequest</code></td><td>Muse-side approval posture (Muse backend only)</td></tr></tbody></table><p>Any other value fails plugin setup fast with a clear error — the plugin never silently runs the wrong posture.</p><h2 id="approval-mode-muse-backend" tabindex="-1">Approval mode (Muse backend) <a class="header-anchor" href="#approval-mode-muse-backend" aria-label="Permalink to &quot;Approval mode (Muse backend)&quot;">​</a></h2><p>By default the bridge selects <code>approvalMode: &quot;onRequest&quot;</code> for every Muse session, so Muse asks through the bridge before side-effectful actions. That forced mode overrides the permission profile configured in Muse itself, so <code>OPENCODE_MUSE_APPROVAL_MODE</code> makes the posture explicit:</p><ul><li><code>host-default</code> omits <code>approvalMode</code>: the Muse host&#39;s configured permission profile applies, exactly as in the native TUI.</li><li>The other four values select that host-defined mode verbatim (&quot;select, never create&quot;).</li></ul><p>When Muse asks for approval, the bridge ends the turn with the offered choices as a lettered list, naming what each choice grants. Reply with one option (letter, number, or name). Anything unrecognized is asked once more, then denied — ambiguity never approves, and your message still runs as a fresh turn afterward instead of being eaten.</p><h2 id="tool-backend" tabindex="-1">Tool backend <a class="header-anchor" href="#tool-backend" aria-label="Permalink to &quot;Tool backend&quot;">​</a></h2><ul><li><code>muse</code> (default, vetted): Muse runs its own tools with its own prompt. OpenCode&#39;s forwarded tool definitions are registered but never executed by OpenCode.</li><li><code>opencode</code> (explicit opt-in): OpenCode executes tools and Muse acts as the model behind them, connected through a private per-session loopback bridge. OpenCode&#39;s native permission evaluation is the only fence (<code>allowAll</code> on the Muse side), and the knob above is ignored.</li></ul><blockquote><p><strong>Current limitation:</strong> the opencode backend is gated to Muse CLI fingerprints with a passing backend live-turn probe (seed: 1.4.14). On Muse 1.4.20 the CLI rejects session MCP servers in <code>run.toolset</code>, so setup fails fast with a clear error pointing at the tracking issue instead of failing every turn. See <a href="/opencode-muse/guide/compatibility.html">Compatibility</a>.</p></blockquote><h2 id="what-the-plugin-never-does" tabindex="-1">What the plugin never does <a class="header-anchor" href="#what-the-plugin-never-does" aria-label="Permalink to &quot;What the plugin never does&quot;">​</a></h2><p>Never reads <code>~/.config/muse</code> (credentials share a file with metadata, so even &quot;safe&quot; fields are off limits) — login state comes only from wire-level probes. Never logs prompts, generated text, media payloads, or raw CLI output. Never auto-updates your Muse binary from under a running host.</p>',13)])])}const f=o(n,[["render",r]]);export{p as __pageData,f as default};
